            path: '/app/output/final_poster.png',
            type: 'png',
            fullPage: true
        });

        await browser.close();
        console.log('Poster generated successfully at /app/output/final_poster.png');
    } catch (error) {
        console.error('Error generating poster:', error);
        process.exit(1);
    }
})();

